import {useState, type ReactNode} from 'react';
import './shell.css';
type Props = {section: string; onSectionChange: (id:string)=>void; inspectorWidth:number; onInspectorWidthChange:(width:number)=>void; children:ReactNode; inspector:ReactNode};
export function ApplicationShell({section,onSectionChange,inspectorWidth,onInspectorWidthChange,children,inspector}:Props){
 const [mobilePane,setMobilePane]=useState<'navigation'|'workspace'|'inspector'>('workspace');
 const width=Math.max(240,Math.min(480,inspectorWidth));
 return <div className="shell" style={{'--inspector-width':width+'px'} as React.CSSProperties}>
  <a className="skip" href="#workspace">Skip to workspace</a>
  <header className="toolbar"><strong>Workspace</strong><div className="phone-controls" aria-label="Visible pane">{(['navigation','workspace','inspector'] as const).map(p=><button key={p} aria-pressed={mobilePane===p} onClick={()=>setMobilePane(p)}>{p}</button>)}</div></header>
  <div className="panes" data-mobile-pane={mobilePane}>
   <nav className="navigation pane" aria-label="Workspace navigation" tabIndex={0}>{[{name:'Workspace',rows:['Overview','Projects']},{name:'Organization',rows:['People','Settings']}].map(group=><section key={group.name}><h2>{group.name}</h2>{group.rows.map(id=><button key={id} aria-current={section===id?'page':undefined} onClick={()=>{onSectionChange(id);setMobilePane('workspace')}}>{id}</button>)}</section>)}</nav>
   <main className="workspace pane" id="workspace" tabIndex={-1}>{children}</main>
   <aside className="inspector pane" aria-label="Inspector" tabIndex={0}><label className="resize">Inspector width<input type="range" min={240} max={480} step={8} value={width} onChange={e=>onInspectorWidthChange(Number(e.target.value))}/></label>{inspector}</aside>
  </div>
 </div>
}
// The application supplies selection and width, and decides whether/how to persist them.
